package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="excepciones_recurso") public class ExcepcionRecurso{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="exr_id")private Long exrId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="rag_id",nullable=false)private Long ragId;@Column(name="exr_fec",nullable=false)private LocalDate exrFec;@Column(name="exr_ini")private LocalTime exrIni;@Column(name="exr_fin")private LocalTime exrFin;@Column(name="exr_dis",nullable=false)private Boolean exrDis;@Column(name="exr_cap")private Integer exrCap;@Column(name="exr_mot",length=300)private String exrMot;@Column(name="exr_usu_mov",nullable=false,length=100)private String exrUsuMov;@Column(name="exr_fec_mov",nullable=false)private LocalDateTime exrFecMov;@Column(name="exr_act",nullable=false)private Boolean exrAct;
 public Long getExrId(){return exrId;}public void setExrId(Long v){exrId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getRagId(){return ragId;}public void setRagId(Long v){ragId=v;}public LocalDate getExrFec(){return exrFec;}public void setExrFec(LocalDate v){exrFec=v;}public LocalTime getExrIni(){return exrIni;}public void setExrIni(LocalTime v){exrIni=v;}public LocalTime getExrFin(){return exrFin;}public void setExrFin(LocalTime v){exrFin=v;}public Boolean getExrDis(){return exrDis;}public void setExrDis(Boolean v){exrDis=v;}public Integer getExrCap(){return exrCap;}public void setExrCap(Integer v){exrCap=v;}public String getExrMot(){return exrMot;}public void setExrMot(String v){exrMot=v;}public String getExrUsuMov(){return exrUsuMov;}public void setExrUsuMov(String v){exrUsuMov=v;}public LocalDateTime getExrFecMov(){return exrFecMov;}public void setExrFecMov(LocalDateTime v){exrFecMov=v;}public Boolean getExrAct(){return exrAct;}public void setExrAct(Boolean v){exrAct=v;}
}
